function startEdit(row){if(!company&&!row){notify('اختر الشركة أولاً، ثم أضف السجل');return}setEdit(row?{...row,data:{...row.data}}:{company,data:Object.fromEntries(spec.fields.map(f=>[f.key,f.type==='number'?'0':f.type==='date'?saudiDate():f.type==='month'?saudiDate().slice(0,7):f.type==='sponsorship'?'yes':f.type==='method'?'bank':f.type==='employment'?'active':f.type==='leave_type'?'annual':f.type==='warning_type'?'first':f.type==='case_status'?'draft':'']))})}
function exportRows(){const fields=module==='employees'?tableFields:fieldsFor,extras=[...new Set(list.flatMap(r=>Object.keys(r.data.extra_fields||{})))];const financial=false;const headers=['الشركة',...fields.map(f=>f.label),...(financial?['الراتب الأساسي (65%)','بدل السكن (25%)','بدل الترحيل (10%)','الاستحقاق السنوي الحالي','الرصيد المتبقي الحالي']:[]),...extras,'مرحلة الاعتماد'];const data=list.map(r=>{const used=rows.filter(x=>x.module==='leave'&&x.status==='approved'&&(x.data.balance_deducted??(!x.data.leave_type||x.data.leave_type==='annual'))&&x.data.employee_id===r.id).reduce((n,x)=>n+Number(x.data.days),0);const service=annualLeave(r.data.hire_date);const balance=r.data.sponsorship==='yes'?(service?service.accrued+Number(r.data.opening_leave||0)-used:'أكمل تاريخ التعيين'):Number(r.data.opening_leave||0)+Number(r.data.legacy_ledger_adjustment||0)-used;return [r.company,...fields.map(f=>module==='employees'?employeeRegisterValue(r,f.key,rows):r.data[f.key]??''),...(financial?[Number(r.data.basic||0),Number(r.data.housing||0),Number(r.data.transport||0),r.data.sponsorship==='yes'?(service?.annual??''):r.data.annual_days||'',balance]:[]),...extras.map(k=>r.data.extra_fields?.[k]??''),states[r.status]||r.status]});const bytes=workbookBytes([headers,...data]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download=module+'-export.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function template(){const bytes=workbookBytes([['الشركة',...(module==='employees'?[...new Set([...employeeRegisterFields.map(f=>f.label),...spec.fields.map(f=>f.label)])]:spec.fields.map(f=>f.label))]]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download=module+'-template.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function readImport(file){try{if(!file)return;if(file.size>2e6)throw Error('الحد الأقصى 2 ميجابايت');const data=file.name.toLowerCase().endsWith('.xlsx')?readXlsx(new Uint8Array(await file.arrayBuffer())):csvParse(await file.text()),headers=data.shift();if(!headers.includes('الشركة'))throw Error('استخدم القالب الذي يتضمن عمود الشركة');if(data.length>500)throw Error('الحد الأقصى 500 سجل لكل دفعة');const aliases={code:['الرقم الوظيفي'],name:['اسم الموظف','الاسم الكامل'],identity:['الهوية أو الإقامة','رقم الهوية/الإقامة'],home_phone:['هاتف الموظف في البلد الأم'],payment_method:['طريقة الصرف'],hire_date:['تاريخ التعيين'],opening_leave:['رصيد افتتاحي للإجازات'],annual_days:['الاستحقاق السنوي'],sponsorship:['حالة الكفالة'],salary:['الأجر الشهري الإجمالي'],job:['المسمى الوظيفي'],project_id:['رقم المشروع','اسم المشروع'],bank:['البنك'],method:['طريقة الصرف']};const prepared=data.map((r,i)=>({line:i+2,company:r[headers.indexOf('الشركة')],data:Object.fromEntries(spec.fields.map(f=>{let j=headers.indexOf(f.label);if(j<0)j=headers.findIndex(h=>(aliases[f.key]||[]).includes(h));let v=r[j]??'';if(relationModules[f.type]&&v){const target=rows.filter(row=>row.module===relationModules[f.type]&&(row.company===r[headers.indexOf('الشركة')]||(row.data._shared_companies||[]).includes(r[headers.indexOf('الشركة')]))&&(row.id===v||String(row.data._legacy?.id)===String(v)||row.data.code===v||row.data.name===v));if(target.length===1)v=target[0].id;}if(f.type==='date'&&/^\d+(\.\d+)?$/.test(v)&&Number(v)>20000)v=new Date(Date.UTC(1899,11,30)+Number(v)*86400000).toISOString().slice(0,10);if(enumOptions[f.type])v=enumOptions[f.type].find(o=>o[0]===v||o[1]===v)?.[0]||v||({sponsorship:'unknown',employment:'needs_review',method:'bank'}[f.type]||'');return [f.key,v]}))}));setImportRows(prepared)}catch(e){notify(e.message)}}
async function confirmImport(){setSaving(true);let ok=0,failed=[];for(const r of importRows){try{await post({action:'save',module,...r});ok++}catch(e){failed.push({...r,error:e.message})}}setImportRows(failed.length?failed:null);notify(`تم حفظ ${ok} سجل. تعذر حفظ ${failed.length} سجل.`);setSaving(false);await refresh()}
